	if len(f.overlay) == 0 {
		return f.index.Records
	}
	out := make([]historyRecord, 0, len(f.index.Records)+len(f.overlay))
	for _, record := range f.index.Records {
		if f.replaced[record.Path] {
			continue
		}
		out = append(out, record)
	}
