	fused, ok := rankHistoryFused(brainDir, index, "history", "embeddings backend", 5, e)
	if !ok {
		t.Fatal("fused ranking unavailable with gate open and vectors synced")
	}
	got := map[string]bool{}
	for _, s := range fused {
		got[s.Record.ID] = true
